def get_f(a, b, c, d, limit):
    pairs = []
    for x in range(limit):
        for y in range(limit):
            pairs.append((x, y))

    # Sort pairs based on (ax+by, cx+dy)
    pairs.sort(key=lambda p: (a*p[0] + b*p[1], c*p[0] + d*p[1]))

    f = {}
    for i, p in enumerate(pairs):
        f[p] = i
    return f

def count_odd(f, limit):
    count = 0
    for x in range(limit):
        for y in range(limit):
            if f[(x, y)] % 2 == 1:
                count += 1
    return count

