def diagonal_f(x, y):
    return (x + y) * (x + y + 1) // 2 + x

def count_diagonal_odd(limit):
    count = 0
    for x in range(limit):
        for y in range(limit):
            if diagonal_f(x, y) % 2 == 1:
                count += 1
    return count

