def get_rank_correct(a, b, c, d, x, y):
    K = a * x + b * y
    count = 0
    if K > 0:
        for x_prime in range((K - 1) // a + 1):
            count += (K - a * x_prime - 1) // b + 1
    for x_prime in range(K // a + 1):
        rem = K - a * x_prime
        if rem % b == 0:
            y_prime = rem // b
            if (x_prime, y_prime) != (x, y):
                if c * x_prime + d * y_prime < c * x + d * y:
                    count += 1
    return count

def solve_for_limit(a, b, c, d, limit):
    count = 0
    for x in range(limit):
        for y in range(limit):
            if get_rank_correct(a, b, c, d, x, y) % 2 == 1:
                count += 1
    return count

